function Icon({ name, size = 20 }) {
  const paths = { leaf: "M20 4C10 2 3 8 5 15c4 7 14 2 15-11ZM5 20 15 9", clock: "M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z", cart: "m3 3 3 2 2 11h10l3-9H6m3 13h.01M18 20h.01", heart: "M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z", shuffle: "m3 5 4 0 10 14h4m-4-4 4 4-4 3M3 19h4L17 5h4m-4-3 4 3-4 4", check: "m5 12 4 4L19 6", close: "m6 6 12 12M6 18 18 6", arrow: "M4 12h16m-6-6 6 6-6 6", search: "M21 21l-5-5M18 10A8 8 0 1 1 2 10a8 8 0 0 1 16 0Z", settings: "M4 7h16M4 17h16M8 4v6m8 4v6", calendar: "M8 2v4m8-4v4M3 10h18M3 5h18v16H3Z", wifi: "M3 8a15 15 0 0 1 18 0M6 12a10 10 0 0 1 12 0m-8 4a4 4 0 0 1 4 0m-2 4h.01", plus: "M12 4v16M4 12h16", book: "M12 5c-4-3-8-2-10-1v15c4-2 7-2 10 0 3-2 6-2 10 0V4c-2-1-6-2-10 1Zm0 0v14" };
  return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d={paths[name] || paths.leaf} /></svg>;
}

export function RecipePhoto({ recipe, className = "", children }) {
  const ref = useRef(null); const [edge, setEdge] = useState(0); const col = recipe.image.cell % 4; const row = Math.floor(recipe.image.cell / 4);
  useEffect(() => { const measure = () => { if (ref.current) setEdge(Math.ceil(Math.max(ref.current.clientWidth, ref.current.clientHeight))); }; measure(); const observer = new ResizeObserver(measure); observer.observe(ref.current); return () => observer.disconnect(); }, []);
  return <div ref={ref} className={`gr-photo ${className}`} role="img" aria-label={`${recipe.title} — illustration`}><div className="gr-photo-surface" style={{ width: edge || "100%", height: edge || "100%", backgroundImage: `url(/courses/recipes-atlas-${recipe.image.atlas}.png)`, backgroundPosition: `${col * 100 / 3}% ${row * 100 / 3}%` }} />{children}</div>;
}

function Modal({ title, subtitle, onClose, children, wide = false }) {
  const ref = useRef(null); const closeRef = useRef(onClose); closeRef.current = onClose;
  useEffect(() => {
    const previous = document.activeElement; const overflow = document.body.style.overflow; document.body.style.overflow = "hidden"; ref.current?.focus();
    const key = (event) => {
      if (event.key === "Escape") closeRef.current();
      if (event.key !== "Tab") return;
      const items = [...ref.current.querySelectorAll("button:not(:disabled), a[href], input:not(:disabled), select:not(:disabled), textarea:not(:disabled), [tabindex='0']")].filter((item) => item.getClientRects().length);
      const first = items[0]; const last = items.at(-1);
      if (!first) { event.preventDefault(); ref.current.focus(); }
      else if (event.shiftKey && (document.activeElement === first || document.activeElement === ref.current)) { event.preventDefault(); last.focus(); }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
    };
    window.addEventListener("keydown", key); return () => { window.removeEventListener("keydown", key); document.body.style.overflow = overflow; previous?.focus?.(); };
  }, []);
  return createPortal(<div className="gr-overlay" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><section ref={ref} tabIndex={-1} role="dialog" aria-modal="true" aria-label={title} className={`gr-modal ${wide ? "gr-modal-wide" : ""}`}><header><div><small>{subtitle}</small><h2>{title}</h2></div><button className="gr-icon" onClick={onClose} aria-label={tr("Fermer")}><Icon name="close" /></button></header>{children}</section></div>, document.body);
}

function RecipeCard({ recipe, state, onOpen, onFavorite, shared = 0, compact = false }) { return <article className={`gr-recipe ${compact ? "gr-recipe-compact" : ""}`}><button className="gr-photo-button" onClick={() => onOpen(recipe.id)} aria-label={`Voir ${recipe.title}`}><RecipePhoto recipe={recipe}><span className="gr-recipe-tag">{recipe.vegan ? tr(" Végétal") : recipe.vegetarian ? tr(" Végé") : recipe.category === "poisson" ? tr(" Poisson") : tr(" Fait maison")}</span></RecipePhoto></button><button className={`gr-favorite ${state.preferences[recipe.id] === "favorite" ? "selected" : ""}`} onClick={() => onFavorite(recipe.id)} aria-label={`Favori : ${recipe.title}`} aria-pressed={state.preferences[recipe.id] === "favorite"}><Icon name="heart" size={18} /></button><div className="gr-recipe-copy"><button onClick={() => onOpen(recipe.id)}><h3>{recipe.title}</h3><p>{recipe.subtitle}</p>{shared > 0 && <small className="gr-shared-ingredients">♻ {shared}{" "}{tr("ingrédient")}{shared > 1 ? "s" : ""}{" "}{tr("en commun")}</small>}</button><footer><span><Icon name="clock" size={14} />{recipe.minutes} min</span><b>≈ {money(recipe.estimateCents / recipe.servings)}<small>/pers.</small></b></footer></div></article>; }

function Household({ state, dispatch, onClose, notify }) {
  const initial = useRef(structuredClone(state.settings));
  const [value, setValue] = useState({ ...state.settings, budget: String(state.settings.budgetCents / 100) });
  const set = (key, input) => setValue((old) => ({ ...old, [key]: input }));
  return <Modal title={tr("À votre goût.")} subtitle={tr("LE FOYER & LES ENVIES")} onClose={onClose}><form className="gr-form" onSubmit={(event) => { event.preventDefault(); const { budget, ...settings } = value; const normalized = { ...settings, people: Number(settings.people), budgetCents: Math.round(Number(budget) * 100), householdConfirmed: true }; const changed = Object.fromEntries(Object.entries(normalized).filter(([key, input]) => JSON.stringify(input) !== JSON.stringify(initial.current[key]))); if (!dispatch("settings", changed)) return; notify(tr("Préférences enregistrées. Vérifiez toujours les étiquettes et traces d'allergènes.")); onClose(); }}><div className="gr-form-row"><label>{tr("Personnes")}<input type="number" min="1" max="12" value={value.people} onChange={(event) => set("people", event.target.value)} required /></label><label>{tr("Budget / période (€)")}<input type="number" min="0" step="1" value={value.budget} onChange={(event) => set("budget", event.target.value)} /></label></div><label>{tr("Adresse de départ")}<input value={value.address} onChange={(event) => set("address", event.target.value)} placeholder={tr("Adresse personnelle, conservée dans votre profil")} maxLength={250} /></label><div className="gr-form-row"><label>{tr("Code postal")}<input value={value.postalCode} onChange={(event) => set("postalCode", event.target.value)} pattern="[0-9]{5}" required /></label><label>{tr("Ville")}<input value={value.city} onChange={(event) => set("city", event.target.value)} maxLength={100} /></label></div><div className="gr-form-row"><label>{tr("Alimentation")}<select value={value.diet} onChange={(event) => set("diet", event.target.value)}><option value="all">{tr("Variée")}</option><option value="vegetarian">{tr("Végétarienne")}</option><option value="vegan">{tr("Végétale")}</option></select></label><label>{tr("Repas à planifier")}<select value={value.meal} onChange={(event) => set("meal", event.target.value)}><option value="dinner">{tr("Dîners")}</option><option value="lunch">{tr("Déjeuners")}</option></select></label></div><label>{tr("Horaire des rappels (Europe/Paris)")}<input type="time" value={value.remindAt} onChange={(event) => set("remindAt", event.target.value)} /></label><fieldset><legend>{tr("Allergènes à exclure")}</legend><div className="gr-pills">{["gluten", tr("crustacés"), tr("œuf"), "poisson", "arachides", "soja", "lait", tr("fruits à coque"), tr("céleri"), "moutarde", tr("sésame"), "sulfites", "lupin", "mollusques"].map((allergen) => <button type="button" className={value.allergens.includes(allergen) ? "active" : ""} key={allergen} onClick={() => set("allergens", value.allergens.includes(allergen) ? value.allergens.filter((item) => item !== allergen) : [...value.allergens, allergen])}>{value.allergens.includes(allergen) ? "✓ " : ""}{allergen}</button>)}</div></fieldset><p className="gr-fine">{tr("Filtres fondés sur les ingrédients du catalogue ; les traces et compositions des marques doivent être vérifiées. Aucune allergie déclarée n'est pas une garantie d'absence.")}</p><label className="gr-checkbox"><input type="checkbox" checked={value.householdConfirmed} onChange={(event) => set("householdConfirmed", event.target.checked)} required />{tr("Je confirme le nombre de personnes et les contraintes ci-dessus.")}</label><button className="gr-primary" type="submit">{tr("Enregistrer mes préférences")}{" "}<Icon name="check" size={18} /></button></form></Modal>;
}

function StoreSettings({ state, dispatch, onClose }) { return <Modal title={tr("Mes enseignes")} subtitle={tr("PAS DE FAUSSE CONNEXION")} onClose={onClose}><p className="gr-fine">{tr("Les liens ouvrent votre compte officiel. Prix et historique nécessitent un relevé/import ; Noyau ne dispose pas encore d'API partenaire pour lire ou créer vos commandes.")}</p><div className="gr-store-settings">{state.stores.map((store) => { const retailer = RETAILERS.find((item) => item.id === store.id); return <StoreForm key={store.id} store={store} retailer={retailer} dispatch={dispatch} />; })}</div></Modal>; }

function StoreForm({ store, retailer, dispatch }) {
  const [value, setValue] = useState({ ...store, minimum: store.minimumCents === null ? "" : store.minimumCents / 100, fees: store.feesCents === null ? "" : store.feesCents / 100 });
  return <form className="gr-form gr-store-form" onSubmit={(event) => { event.preventDefault(); const { minimum, fees, ...settings } = value; dispatch("store", { ...settings, minimumCents: minimum === "" ? null : Math.round(Number(minimum) * 100), feesCents: fees === "" ? null : Math.round(Number(fees) * 100) }); }}><h3><i className="gr-store-logo" style={{ background: retailer.color }}>{retailer.name.slice(0, 1)}</i>{retailer.name}<small>{retailer.mode === "delivery" ? tr("Livraison") : tr("Drive")}</small></h3><a href={retailer.locator} target="_blank" rel="noreferrer">{tr("Choisir le point de retrait / tester mon adresse ↗")}</a><label>{tr("Point de retrait / zone")}<input value={value.storeName} onChange={(event) => setValue({ ...value, storeName: event.target.value })} maxLength={150} /></label><div className="gr-form-row"><label>{tr("Minimum (€)")}<input type="number" min="0" step="0.01" value={value.minimum} onChange={(event) => setValue({ ...value, minimum: event.target.value })} /></label><label>{tr("Frais totaux (€)")}<input type="number" min="0" step="0.01" value={value.fees} onChange={(event) => setValue({ ...value, fees: event.target.value })} /></label></div>{[["enabled", tr("Comparer cette enseigne")], ["storeConfirmed", tr("Ce magasin / cette adresse est éligible")], ["minimumConfirmed", tr("Minimum et frais du créneau vérifiés")], ["loyalty", tr("J'utilise la carte fidélité de cette enseigne")]].map(([key, label]) => <label className="gr-checkbox" key={key}><input type="checkbox" checked={value[key]} onChange={(event) => setValue({ ...value, [key]: event.target.checked })} />{label}</label>)}<p className="gr-fine">{retailer.note} <a href={retailer.source} target="_blank" rel="noreferrer">{tr("Conditions officielles ↗")}</a></p><button className="gr-secondary" type="submit">{tr("Enregistrer")}{" "}{retailer.name}</button></form>;
}

function OfferForm({ state, dispatch, request, onClose, notify, candidate }) {
  const [value, setValue] = useState({ ingredientId: candidate ? "" : Object.keys(INGREDIENTS)[0], storeId: candidate?.storeId || "carrefour", packQuantity: candidate ? "" : 500, price: candidate ? candidate.priceCents / 100 : "", discount: "0", loyalty: "0", sourceUrl: candidate?.sourceUrl || "", validUntil: "", loyaltyRequired: false, bundleQuantity: "", bundlePrice: "" });
  const [busy, setBusy] = useState(false); const [error, setError] = useState("");
  const set = (key, input) => setValue((old) => ({ ...old, [key]: input }));
  async function fetchPrice() { setBusy(true); setError(""); try { const data = await request("/api/groceries/product-page", { method: "POST", body: JSON.stringify({ url: value.sourceUrl, storeId: value.storeId }) }); if (data.products.length !== 1) throw new Error(tr("Plusieurs produits détectés : relevez le prix du bon produit manuellement.")); set("price", data.products[0].priceCents / 100); notify("Prix public lu ; confirmez le magasin, le produit et le conditionnement."); } catch (err) { setError(err.message); } finally { setBusy(false); } }
  return <Modal title={tr("Un vrai prix, une vraie source.")} subtitle={tr("RELEVÉ DE PRIX / PROMOTION")} onClose={onClose}><form className="gr-form" onSubmit={(event) => { event.preventDefault(); if (!dispatch("offer", { id: crypto.randomUUID(), ingredientId: value.ingredientId, storeId: value.storeId, packQuantity: Number(value.packQuantity), priceCents: Math.round(Number(value.price) * 100), instantDiscountCents: Math.round(Number(value.discount) * 100), loyaltyCents: Math.round(Number(value.loyalty) * 100), loyaltyRequired: value.loyaltyRequired, sourceUrl: value.sourceUrl, observedAt: candidate?.observedAt || new Date().toISOString(), provenance: candidate ? "public-page" : "manual", label: candidate?.label || "", validUntil: value.validUntil ? new Date(parisInstant(addDays(value.validUntil, 1), "00:00").getTime() - 1).toISOString() : null, ...(value.bundleQuantity ? { bundleQuantity: Number(value.bundleQuantity), bundlePriceCents: Math.round(Number(value.bundlePrice) * 100) } : {}) })) return; onClose(); }}>
  {candidate && <p className="gr-fine"><strong>{tr("Relevé public :")}{" "}{candidate.label}</strong>{" "}{tr("· vérifiez magasin, produit et conditionnement avant comparaison. Les remises fidélité et dates ne sont pas déduites automatiquement.")}</p>}<label>{tr("Produit")}<select required value={value.ingredientId} onChange={(event) => set("ingredientId", event.target.value)}><option value="" disabled>{tr("Choisir le produit correspondant")}</option>{Object.values(INGREDIENTS).map((item) => <option key={item.id} value={item.id}>{item.label}</option>)}</select></label><div className="gr-form-row"><label>{tr("Enseigne")}<select value={value.storeId} onChange={(event) => set("storeId", event.target.value)}>{RETAILERS.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>{tr("Quantité du paquet (")}{(INGREDIENTS[value.ingredientId]?.unit || tr("unité à confirmer"))})<input type="number" min="0.1" step="0.1" required value={value.packQuantity} onChange={(event) => set("packQuantity", event.target.value)} /></label></div><label>{tr("URL officielle produit / catalogue")}<input type="url" required value={value.sourceUrl} onChange={(event) => set("sourceUrl", event.target.value)} placeholder="https://www.carrefour.fr/..." /></label><button type="button" className="gr-secondary" disabled={busy || !value.sourceUrl} onClick={fetchPrice}>{busy ? tr("Lecture de la page…") : tr("Lire le prix public de cette page")}</button>{error && <p className="gr-error">{error}</p>}<div className="gr-form-row"><label>{tr("Prix du paquet (€)")}<input type="number" required min="0" step="0.01" value={value.price} onChange={(event) => set("price", event.target.value)} /></label><label>{tr("Remise immédiate / paquet (€)")}<input type="number" min="0" step="0.01" value={value.discount} onChange={(event) => set("discount", event.target.value)} /></label></div><div className="gr-form-row"><label>{tr("Cagnotte différée / paquet (€)")}<input type="number" min="0" step="0.01" value={value.loyalty} onChange={(event) => set("loyalty", event.target.value)} /></label><label>{tr("Fin de la promotion")}<input type="date" value={value.validUntil} onChange={(event) => set("validUntil", event.target.value)} /></label></div><div className="gr-form-row"><label>{tr("Paquets par lot (facultatif)")}<input type="number" min="2" max="100" step="1" value={value.bundleQuantity} onChange={(event) => set("bundleQuantity", event.target.value)} /></label><label>{tr("Prix final du lot (€)")}<input type="number" min="0" step="0.01" required={Boolean(value.bundleQuantity)} value={value.bundlePrice} onChange={(event) => set("bundlePrice", event.target.value)} /></label></div><label className="gr-checkbox"><input type="checkbox" checked={value.loyaltyRequired} onChange={(event) => set("loyaltyRequired", event.target.checked)} />{tr("Ce prix nécessite la carte fidélité")}</label><p className="gr-fine">{tr("Ne ressaisissez pas une remise déjà incluse dans le prix affiché. Coupons de panier non déduits automatiquement. Saisissez seulement les remises cumulables et applicables à votre compte. Les cagnottes ne sont jamais déduites du montant à payer aujourd'hui. Relevés valables")}{" "}{state.settings.priceMaxAgeHours}{" "}{tr("h maximum.")}</p><button className="gr-primary" type="submit">{tr("Enregistrer ce relevé")}</button></form></Modal>;
}

function OrderImport({ state, dispatch, onClose, notify }) {
  const [text, setText] = useState(""); const [error, setError] = useState("");
  return <Modal title={tr("Vos habitudes, pas des suppositions.")} subtitle={tr("IMPORTER UN HISTORIQUE")} onClose={onClose}><p className="gr-fine">{tr("Export ou relevé CSV : date;enseigne;produit;quantité;prix_ligne_euros. Produits par identifiant ou libellé du catalogue. Aucune lecture de compte sans connexion partenaire.")}</p><form className="gr-form" onSubmit={(event) => { event.preventDefault(); try { const orders = new Map(); for (const line of text.trim().split(/\r?\n/)) { const [date, storeId, name, quantity, price] = line.split(";").map((part) => part.trim()); if (date.toLowerCase() === "date") continue; const ingredient = Object.values(INGREDIENTS).find((item) => item.id === name || item.label.toLocaleLowerCase("fr") === name.toLocaleLowerCase("fr")); if (!ingredient) throw new Error(tr("Produit à mapper : {0}", name)); const id = `import-${storeId}-${date}`; const order = orders.get(id) || { id, storeId, date, lines: [] }; order.lines.push({ ingredientId: ingredient.id, quantity: Number(quantity.replace(",", ".")), priceCents: Math.round(Number(price.replace(",", ".")) * 100) }); orders.set(id, order); } if (!orders.size) throw new Error(tr("Historique vide.")); [...orders.values()].reduce((next, payload) => applyGroceryOperation(next, { type: "order", payload }), state); for (const order of orders.values()) dispatch("order", order); notify(tr("{0} commande(s) importée(s).", orders.size)); onClose(); } catch (err) { setError(err.message); } }}><textarea rows={9} value={text} onChange={(event) => setText(event.target.value)} placeholder={"date;enseigne;produit;quantité;prix_ligne_euros\n2026-10-20;carrefour;milk;1000;1,20"} required />{error && <p className="gr-error">{error}</p>}<button className="gr-primary" type="submit">{tr("Importer et trouver mes habitudes")}</button></form></Modal>;
}

function PriceImport({ state, dispatch, onClose, notify }) {
  const [text, setText] = useState(""); const [error, setError] = useState("");
  return <Modal title={tr("Relevés de prix en une fois.")} subtitle={tr("IMPORT CSV SOURCÉ, SANS CONNEXION FICTIVE")} onClose={onClose}><p className="gr-fine">{tr("Colonnes séparées par ; : produit;enseigne;quantité_paquet;prix_euros;url_officielle;date_relevé_ISO. Identifiants produits du catalogue ; ne pas importer un prix national comme un prix de votre magasin sans vérification.")}</p><form className="gr-form" onSubmit={(event) => { event.preventDefault(); try { const offers = text.trim().split(/\r?\n/).filter(Boolean).filter((line) => !line.toLowerCase().startsWith("produit;")).map((line) => { const [ingredientId, storeId, quantity, price, sourceUrl, observedAt] = line.split(";").map((value) => value.trim()); if (!quantity || !price || !sourceUrl || !observedAt) throw new Error(tr("Ligne de prix incomplète.")); return { id: crypto.randomUUID(), ingredientId, storeId, packQuantity: Number(quantity.replace(",", ".")), priceCents: Math.round(Number(price.replace(",", ".")) * 100), sourceUrl, observedAt }; }); if (!offers.length || offers.length > 200) throw new Error(tr("Importer entre 1 et 200 relevés à la fois.")); offers.reduce((next, payload) => applyGroceryOperation(next, { type: "offer", payload }), state); for (const offer of offers) dispatch("offer", offer); notify(tr("{0} relevé(s) ajouté(s), sans inventer les conditions du magasin.", offers.length)); onClose(); } catch (err) { setError(err.message); } }}><input type="file" accept=".csv,.txt,text/csv" aria-label={tr("Fichier de relevés")} onChange={async (event) => { const file = event.target.files?.[0]; if (file && file.size <= 500000) setText(await file.text()); else setError(tr("Fichier trop volumineux (500 Ko maximum).")); }} /><textarea rows={9} maxLength={500000} value={text} onChange={(event) => setText(event.target.value)} required placeholder="rice;carrefour;1000;2,30;https://www.carrefour.fr/produit;2026-10-27T12:00:00Z" />{error && <p className="gr-error">{error}</p>}<button className="gr-primary" type="submit">{tr("Vérifier et importer les relevés")}</button></form></Modal>;
}

function CustomRecipeForm({ recipe, dispatch, request, onClose, notify }) {
  const [rawIngredients, setRawIngredients] = useState([]); const [importing, setImporting] = useState(false); const [error, setError] = useState(""); const [confirmed, setConfirmed] = useState(false);
  const [value, setValue] = useState(() => recipe ? { title: recipe.title, subtitle: recipe.subtitle, minutes: recipe.minutes, servings: recipe.servings, sourceUrl: recipe.sourceUrl || "", steps: recipe.steps.join("\n"), vegetarian: recipe.vegetarian, vegan: recipe.vegan, ingredients: recipe.ingredients.map((item) => ({ ...item })) } : { title: "", subtitle: "", minutes: 30, servings: 2, sourceUrl: "", steps: "", vegetarian: false, vegan: false, ingredients: [{ ingredientId: "tomato", quantity: 200 }] });
  const set = (key, next) => setValue((current) => ({ ...current, [key]: next }));
  const update = (index, patch) => set("ingredients", value.ingredients.map((item, i) => i === index ? { ...item, ...patch } : item));
  return <Modal title={tr("Ma recette")} subtitle={tr("CRÉER UN PLAT PERSONNEL")} onClose={onClose} wide><form className="gr-form" onSubmit={(event) => { event.preventDefault(); const payload = { ...value, id: recipe?.id || `custom-${crypto.randomUUID()}`, minutes: Number(value.minutes), servings: Number(value.servings), ingredients: value.ingredients.map((item) => ({ ...item, quantity: Number(item.quantity) })), steps: value.steps.split(/\n+/).map((step) => step.trim()).filter(Boolean) }; if (!dispatch("custom-recipe", payload)) return; notify(tr("Recette enregistrée sur ce profil et disponible hors ligne.")); onClose(); }}>
    <label>{tr("Nom de la recette")}<input value={value.title} onChange={(event) => set("title", event.target.value)} maxLength={120} required /></label><label>{tr("Description")}<input value={value.subtitle} onChange={(event) => set("subtitle", event.target.value)} maxLength={180} /></label>
    <div className="gr-form-row"><label>{tr("Temps (minutes)")}<input type="number" min="1" max="1440" value={value.minutes} onChange={(event) => set("minutes", event.target.value)} required /></label><label>{tr("Portions")}<input type="number" min="1" max="12" value={value.servings} onChange={(event) => set("servings", event.target.value)} required /></label></div>
    <label>{tr("Lien HTTPS de la recette (facultatif)")}<input type="url" value={value.sourceUrl} onChange={(event) => set("sourceUrl", event.target.value)} placeholder="https://…" /></label><button type="button" className="gr-secondary" disabled={importing || !value.sourceUrl} onClick={async () => { setImporting(true); setError(""); try { const data = await request("/api/groceries/recipe-import", { method: "POST", body: JSON.stringify({ url: value.sourceUrl }) }); setValue((old) => ({ ...old, title: data.title, subtitle: data.subtitle, minutes: data.minutes, servings: data.servings, steps: data.steps.join("\n"), sourceUrl: data.sourceUrl, ingredients: [] })); setRawIngredients(data.rawIngredients); setConfirmed(false); } catch (reason) { setError(reason.message); } finally { setImporting(false); } }}>{importing ? tr("Lecture…") : tr("Importer depuis le lien")}</button><p className="gr-fine">{tr("Import public 750g, CuisineAZ et Marmiton selon accès et règles du site ; associez et vérifiez chaque ingrédient et quantité ci-dessous.")}</p>{error && <p className="gr-error" role="alert">{error}</p>}{rawIngredients.length > 0 && <div className="gr-imported-ingredients"><strong>{tr("Ingrédients trouvés dans la recette source")}</strong><ul>{rawIngredients.map((line, index) => <li key={index}>{line}</li>)}</ul><p className="gr-fine">{tr("Associez-les aux produits ci-dessous ; quantités et unités ne sont pas converties automatiquement.")}</p><label className="gr-checkbox"><input type="checkbox" checked={confirmed} onChange={(event) => setConfirmed(event.target.checked)} required />{tr("J’ai vérifié les ingrédients et quantités.")}</label></div>}
    <fieldset><legend>{tr("Ingrédients")}</legend>{value.ingredients.map((item, index) => <div className="gr-custom-ingredient" key={index}><select aria-label={tr("Ingrédient {0}", index + 1)} value={item.ingredientId} onChange={(event) => update(index, { ingredientId: event.target.value })}>{Object.values(INGREDIENTS).map((ingredient) => <option key={ingredient.id} value={ingredient.id}>{ingredient.label}</option>)}</select><input aria-label={tr("Quantité {0}", index + 1)} type="number" min="0.01" max="100000" step="any" value={item.quantity} onChange={(event) => update(index, { quantity: event.target.value })} required /><span>{INGREDIENTS[item.ingredientId].unit}</span><button type="button" className="gr-icon" disabled={value.ingredients.length === 1} onClick={() => set("ingredients", value.ingredients.filter((_, i) => i !== index))} aria-label={tr("Retirer ingrédient {0}", index + 1)}>×</button></div>)}<button type="button" className="gr-secondary" onClick={() => { const next = Object.keys(INGREDIENTS).find((id) => !value.ingredients.some((item) => item.ingredientId === id)); if (next) set("ingredients", [...value.ingredients, { ingredientId: next, quantity: INGREDIENTS[next].referenceQuantity }]); }}>{tr("＋ Ingrédient")}</button></fieldset>
    <label>{tr("Étapes (une par ligne)")}<textarea value={value.steps} onChange={(event) => set("steps", event.target.value)} rows={5} required /></label><label className="gr-checkbox"><input type="checkbox" checked={value.vegetarian} onChange={(event) => setValue((old) => ({ ...old, vegetarian: event.target.checked, vegan: event.target.checked ? old.vegan : false }))} />{tr("Je confirme que ce plat est végétarien")}</label><label className="gr-checkbox"><input type="checkbox" checked={value.vegan} onChange={(event) => setValue((old) => ({ ...old, vegan: event.target.checked, vegetarian: event.target.checked ? true : old.vegetarian }))} />{tr("Je confirme que ce plat est végétalien")}</label><p className="gr-fine">{tr("Allergènes et traces à vérifier : une recette personnelle n’est pas considérée sûre pour une allergie déclarée.")}</p><button className="gr-primary" type="submit">{tr("Enregistrer ma recette")}</button>
  </form></Modal>;
}

function GroceryDevices({ request, onClose, notify }) {
  const [devices, setDevices] = useState([]); const [error, setError] = useState("");
  useEffect(() => { request("/api/groceries/devices").then((data) => setDevices(data.devices)).catch((err) => setError(err.message)); }, [request]);
  return <Modal title={tr("Mes appareils Courses")} subtitle={tr("ACCÈS LIMITÉS ET RÉVOCABLES")} onClose={onClose}><p className="gr-fine">{tr("Chaque accès expire après 90 jours et ne permet ni de lire les agents ni de créer une commande. Révoquez un téléphone perdu immédiatement.")}</p>{devices.map((device) => <article className="gr-checkout-cart" key={device.id}><h3>{device.name}</h3><p className="gr-fine">{tr("Expiration :")}{" "}{new Date(device.expiresAt).toLocaleDateString(LOCALE)}</p><button className="gr-secondary" onClick={async () => { try { await request(`/api/groceries/devices/${device.id}`, { method: "DELETE" }); setDevices((current) => current.filter((item) => item.id !== device.id)); notify(tr("Accès appareil révoqué.")); } catch (err) { setError(err.message); } }}>{tr("Révoquer cet accès")}</button></article>)}{!devices.length && <p className="gr-fine">{tr("Aucun accès associé, ou connexion au serveur requise.")}</p>}{error && <p className="gr-error">{error}</p>}</Modal>;
}

export default function GroceriesView({ profileId, request: requestOverride }) {
  const [state, setState] = useState(null); const [sync, setSync] = useState({ pending: 0 }); const [network, setNetwork] = useState(false); const [tab, setTab] = useState("discover"); const [filter, setFilter] = useState("all"); const [family, setFamily] = useState("all"); const [visibleCount, setVisibleCount] = useState(48); const [search, setSearch] = useState(""); const [selected, setSelected] = useState(null); const [editingRecipe, setEditingRecipe] = useState(null); const [modal, setModal] = useState(null); const [toast, setToast] = useState(""); const [checkout, setCheckout] = useState(null); const [catalogueScan, setCatalogueScan] = useState(null); const [offerCandidate, setOfferCandidate] = useState(null); const [busy, setBusy] = useState(false); const [extra, setExtra] = useState("milk"); const clientRef = useRef(null);
  const requestRef = useRef(requestOverride); requestRef.current = requestOverride;
  const request = useMemo(() => (path, options) => requestRef.current ? requestRef.current(path, options) : groceryRequest(profileId, path, options), [profileId]);
  useEffect(() => {
    const client = new GroceryClient({ profileId, storageId: `${nativeServer() || "unpaired"}:${profileId}`, request, onChange: (next, status) => { setState(next); setSync(status); } }); clientRef.current = client; client.publish();
    let disposed = false; const refresh = () => client.sync().then(() => { if (!disposed) setNetwork(true); }).catch(() => { if (!disposed) setNetwork(false); }); refresh();
    const timer = setInterval(refresh, 15000); const listener = () => refresh(); window.addEventListener("online", listener); window.addEventListener("noyau:network-return", listener); document.addEventListener("visibilitychange", listener);
    return () => { disposed = true; clearInterval(timer); window.removeEventListener("online", listener); window.removeEventListener("noyau:network-return", listener); document.removeEventListener("visibilitychange", listener); clientRef.current = null; };
  }, [profileId, request]);
  useEffect(() => {
    if (!network) return; let stopped = false; let timer;
    const scan = async () => { try { const result = await request("/api/groceries/catalogues"); if (!stopped) { setCatalogueScan(result); timer = setTimeout(scan, result.running ? 5000 : 6 * 3600000); } } catch { if (!stopped) { setCatalogueScan(null); timer = setTimeout(scan, 60000); } } };
    scan(); return () => { stopped = true; clearTimeout(timer); };
  }, [network, request]);
  useEffect(() => { setVisibleCount(48); }, [search, filter, family]);
  useEffect(() => { if (!toast) return; const timer = setTimeout(() => setToast(""), 6000); return () => clearTimeout(timer); }, [toast]);
  useEffect(() => { if (state && isNative) { const timer = setTimeout(() => scheduleMenuReminders(state, { profileId }).catch(() => {}), 350); return () => clearTimeout(timer); } }, [JSON.stringify(state?.plan), state?.settings.reminders, state?.settings.remindAt, profileId]);
  function dispatch(type, payload) { try { const next = clientRef.current.dispatch(type, payload); clientRef.current.sync().then(() => setNetwork(true)).catch(() => setNetwork(false)); return next; } catch (error) { setToast(error.message); return null; } }
  if (!state) return <div className="gr-loading">{" "}{tr("Préparons de bonnes choses…")}</div>;
  const daily = suggestions(state); const sharedIds = selectedIngredientIds(state); const accepted = state.plan.filter((slot) => slot.status === "accepted"); const list = shoppingList(state); const comparison = compareBaskets(state); const estimate = list.reduce((sum, line) => sum + line.estimateCents, 0); const frequent = frequentProducts(state);
  const catalog = daily.filter((recipe) => recipeMatches(recipe, { search, filter, family, preferences: state.preferences }));
  const recipe = selected ? recipeFor(state, selected) : null;
  const changeRecipe = (direction) => { const choices = catalog.length ? catalog : daily.length ? daily : RECIPES; const index = choices.findIndex((item) => item.id === selected); setSelected(choices[index < 0 ? direction > 0 ? 0 : choices.length - 1 : (index + direction + choices.length) % choices.length].id); };
  const favorite = (id) => dispatch("preference", { recipeId: id, value: state.preferences[id] === "favorite" ? "neutral" : "favorite" });
  const plan = () => { if (state.plan.length && !window.confirm(tr("Remplacer les propositions du menu actuel ? Vos favoris et votre placard restent conservés."))) return; if (dispatch("plan", { start: dateParis() })) setTab("week"); };
  const chooseRecipe = (id) => { if (!state.settings.householdConfirmed) { setModal("household"); return; } let next = state; if (!next.plan.length) next = dispatch("plan", { start: dateParis() }); const slot = next?.plan.find((item) => item.status !== "accepted"); if (!slot) { setToast(tr("Tous les repas sont validés : remplacez un plat depuis Mon menu.")); return; } dispatch("slot", { id: slot.id, recipeId: id, status: "accepted" }); setSelected(null); setToast(tr("Plat ajouté à votre menu et à la liste de courses.")); };
  const replace = (slot) => { const used = new Set(state.plan.map((item) => item.recipeId)); const alternative = daily.find((item) => !used.has(item.id)) || daily.find((item) => item.id !== slot.recipeId); if (alternative) dispatch("slot", { id: slot.id, recipeId: alternative.id }); };
  async function prepareCheckout() { setBusy(true); try { if (sync.pending || sync.conflict || !network) throw new Error(tr("Synchronisez le panier avant de préparer le transfert.")); const draft = await request("/api/groceries/checkout", { method: "POST", body: "{}" }); setCheckout(draft); } catch (error) { setToast(error.message); } finally { setBusy(false); } }
  async function associate() { try { const endpoint = window.prompt(tr("URL HTTPS publique dédiée (ou URL privée de la maison) terminée par /api/mobile/groceries. Ne publiez pas les autres routes Noyau.")); if (!endpoint) return; const url = new URL(endpoint); if (url.protocol !== "https:" || url.pathname.replace(/\/$/, "") !== "/api/mobile/groceries" || url.username || url.password || url.search || url.hash) throw new Error(tr("Endpoint HTTPS dédié invalide.")); const device = await request("/api/groceries/devices", { method: "POST", body: JSON.stringify({ name: isNative ? tr("Application mobile") : tr("Session navigateur") }) }); await saveGroceryDevice(profileId, { ...device, endpoint: endpoint.replace(/\/$/, "") }); setToast(tr("Appareil associé pour Courses uniquement, révocable depuis la liste des appareils.")); } catch (error) { setToast(error.message); } }
  return <div className="groceries-app">
    <div className="gr-topline"><span><Icon name="leaf" size={16} />{" "}{tr("Votre cuisine, simplifiée.")}</span><button className={`gr-sync ${network ? "online" : ""}`} onClick={() => clientRef.current.sync().then(() => setNetwork(true)).catch(() => setNetwork(false))}><Icon name="wifi" size={14} />{sync.conflict ? tr("Conflit à résoudre") : sync.pending ? tr("{0} changement(s) à synchroniser", sync.pending) : network ? tr("À jour · synchronisé") : tr("Disponible hors ligne")}</button></div>
    <div className="gr-heading"><div><p className="gr-eyebrow">{tr("LA BONNE IDÉE DU JOUR")}</p><h1>{tr("Moins de courses.")}<br /><em>{tr("Plus de bonnes choses.")}</em></h1><p>{tr("Des plats à aimer, un panier bien pensé, et rien en double.")}</p></div><button className="gr-personal" onClick={() => setModal("household")}><span><Icon name="heart" /></span><div><b>{state.settings.people} {tr(state.settings.people > 1 ? "personnes" : "personne")}</b><small>{state.settings.city || tr("Mon foyer")}</small></div><Icon name="settings" size={18} /></button></div>
    {sync.conflict && <div className="gr-alert" role="alert"><b>{tr("Un autre appareil a modifié le menu.")}</b>{" "}{tr("Vos choix locaux restent conservés.")}<div><button onClick={() => clientRef.current.sync({ rebase: true }).catch((error) => setToast(error.message))}>{tr("Réappliquer mes choix sur la nouvelle version")}</button><button onClick={() => { if (window.confirm(tr("Abandonner les modifications locales en attente ?"))) clientRef.current.useServer(); }}>{tr("Garder la version serveur")}</button></div></div>}
    <nav className="gr-tabs" aria-label={tr("Courses")}><button className={tab === "discover" ? "active" : ""} onClick={() => setTab("discover")}><Icon name="book" />{tr("À cuisiner")}</button><button className={tab === "week" ? "active" : ""} onClick={() => setTab("week")}><Icon name="calendar" />{tr("Mon menu")}{" "}<small>{accepted.length}/{state.settings.days}</small></button><button className={tab === "basket" ? "active" : ""} onClick={() => setTab("basket")}><Icon name="cart" />{tr("Mon panier")}{" "}<small>{list.filter((line) => line.needed > 0).length}</small></button><button className={tab === "deals" ? "active" : ""} onClick={() => setTab("deals")}><Icon name="settings" />{tr("Bons plans")}</button><button className={tab === "history" ? "active" : ""} onClick={() => setTab("history")}><span>↻</span>{tr("Mes habitudes")}</button></nav>
    {tab === "discover" && <>
      <section className="gr-hero"><div className="gr-hero-copy"><span className="gr-badge">{" "}{tr("VOTRE SÉLECTION DU JOUR")}</span><h2>{tr("Ce soir, on fait")}<br />{tr("simple & délicieux.")}</h2><p>{tr("Des idées généreuses à faire défiler.")}<br />{tr("Gardez vos coups de cœur, changez le reste.")}</p><button className="gr-primary" onClick={plan}>{tr("Composer mon menu")}{" "}<Icon name="arrow" size={18} /></button><small>{tr("7 ou 14 jours · aucune recette imposée")}</small></div><div className="gr-hero-photo" onClick={() => setSelected(daily[0]?.id)}><RecipePhoto recipe={daily[0] || RECIPES[0]} /><span className="gr-floating"> {daily[0]?.title || tr("À votre goût")}<small>{tr("Fait maison. À votre rythme.")}</small></span></div><span className="gr-hero-spark"></span></section>
      {!state.settings.householdConfirmed && <button className="gr-onboarding" onClick={() => setModal("household")}><span><Icon name="book" /></span><div><b>{tr("Commençons par ce que vous aimez.")}</b><small>{tr("Personnes, budget et allergies à confirmer avant de valider un menu.")}</small></div><Icon name="arrow" /></button>}
      <section className="gr-section-head"><div><p className="gr-eyebrow">{tr("INSPIRATION SANS ROUTINE")}</p><h2>{tr("Qu'est-ce qui vous ferait plaisir ?")}</h2>{sharedIds.size > 0 && <p className="gr-fine">{tr("D’abord les plats avec le plus d’ingrédients communs à vos repas choisis.")}</p>}<button className="gr-secondary" onClick={() => { setEditingRecipe(null); setModal("custom-recipe"); }}>{tr("＋ Ajouter ma recette")}</button></div><label className="gr-search"><Icon name="search" size={18} /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder={tr("Un plat, une envie…")} aria-label={tr("Chercher une recette")} /></label></section>
      <div className="gr-filters">{[["all", "", tr("Tout découvrir")], ["quick", "", "25 min ou moins"], ["vegetarian", "", tr("Végétarien")], ["vegan", "", tr("100 % végétal")], ["budget", "", tr("Petit budget")], ["favorites", "♡", tr("Mes favoris")]].map(([id, icon, label]) => <button key={id} className={filter === id ? "active" : ""} onClick={() => setFilter(id)}>{icon} {label}</button>)}</div>
      <div className="gr-catalog-bar"><label><span>{" "}{tr("Explorer par famille")}</span><select aria-label={tr("Famille de recettes")} value={family} onChange={(event) => setFamily(event.target.value)}><option value="all">{tr("Toutes les familles")}</option><option value="essentials">{tr("Les incontournables")}</option><option value="personal">{" "}{tr("Mes recettes")}</option>{RECIPE_FAMILIES.map((item) => <option key={item.id} value={item.id}>{item.label}</option>)}</select></label><p aria-live="polite"><b>{catalog.length}</b>{" "}{tr("idée")}{catalog.length > 1 ? "s" : ""}{" "}{tr("pour vous")}{" "}<small>sur {RECIPES.length + (state.customRecipes || []).length} recettes</small></p></div>
      <div className="gr-recipe-grid">{catalog.slice(0, visibleCount).map((item) => <RecipeCard key={item.id} recipe={item} state={state} onOpen={setSelected} onFavorite={favorite} shared={sharedIngredientCount(item, sharedIds)} />)}</div>{!catalog.length && <div className="gr-empty"><h3>{tr("Aucune recette dans cette sélection.")}</h3><p>{tr("Changez de filtre ou vos exclusions ; rien n'est ajouté sans votre accord.")}</p><button className="gr-secondary" onClick={() => { setFilter("all"); setFamily("all"); setSearch(""); }}>{tr("Revoir le catalogue")}</button></div>}
      {catalog.length > visibleCount && <div className="gr-catalog-more"><button className="gr-primary" onClick={() => setVisibleCount((count) => count + 48)}>{tr("Encore des idées")}{" "}<Icon name="plus" size={18} /></button><small>{Math.min(visibleCount, catalog.length)}{" "}{tr("recettes affichées sur")}{" "}{catalog.length}{" "}{tr("· la recherche explore tout le catalogue")}</small></div>}
      <p className="gr-fine gr-disclaimer">{RECIPES.length}{" "}{tr("recettes illustrées · visuels générés et indicatifs, certaines illustrations partagées par famille · coûts par portion = repères d'ingrédients, pas devis magasin.")}</p>
    </>}
    {tab === "week" && <><section className="gr-section-head"><div><p className="gr-eyebrow">{tr("ON S'ORGANISE SANS S'ENFERMER")}</p><h2>{tr("Votre menu, vos envies.")}</h2></div><div className="gr-actions"><div className="gr-segment">{[7, 14].map((days) => <button className={state.settings.days === days ? "active" : ""} key={days} onClick={() => dispatch("settings", { days })}>{days} jours</button>)}</div><button className="gr-primary" onClick={plan}><Icon name="shuffle" size={17} />{tr("Proposer un menu")}</button></div></section><div className="gr-menu-grid">{state.plan.map((slot) => { const item = recipeFor(state, slot.recipeId); if (!item) return null; return <article className={`gr-menu-card ${slot.status}`} key={slot.id}><header><b>{new Intl.DateTimeFormat(LOCALE, { weekday: "long", day: "numeric", month: "short" }).format(new Date(`${slot.date}T12:00:00`))}</b><span>{slot.status === "accepted" ? tr("✓ Validé") : slot.status === "rejected" ? tr("Écarté") : tr("À choisir")}</span></header><button className="gr-photo-button" onClick={() => setSelected(item.id)}><RecipePhoto recipe={item} /></button><h3>{item.title}</h3><p>{item.minutes}{" "}{tr("min ·")}{" "}{slot.portions} portions</p><footer><button className="gr-secondary" onClick={() => replace(slot)} aria-label={`Remplacer ${item.title}`}><Icon name="shuffle" size={16} />{tr("Changer")}</button><button className={slot.status === "accepted" ? "gr-accepted" : "gr-primary"} onClick={() => { if (!state.settings.householdConfirmed) setModal("household"); else dispatch("slot", { id: slot.id, status: slot.status === "accepted" ? "proposed" : "accepted" }); }}><Icon name="check" size={16} />{slot.status === "accepted" ? tr("Choisi") : tr("Choisir")}</button><button className="gr-icon" onClick={() => dispatch("slot", { id: slot.id, status: "rejected" })} aria-label={`Refuser ${item.title}`}><Icon name="close" size={16} /></button></footer></article>; })}</div>{!state.plan.length && <div className="gr-empty"><h3>{tr("Une semaine plus légère commence ici.")}</h3><p>{tr("Proposez un menu, puis acceptez ou remplacez chaque plat.")}</p><button className="gr-primary" onClick={plan}>{tr("Découvrir mon premier menu")}</button></div>}<div className="gr-tools"><button className="gr-secondary" onClick={() => exportMenuCalendar(menuCalendar(state, new Date(), profileId)).catch((error) => setToast(error.message))}>{" "}{tr("Exporter les repas au calendrier")}</button><button className="gr-secondary" onClick={async () => { const result = await scheduleMenuReminders({ ...state, settings: { ...state.settings, reminders: true } }, { requestPermission: true, profileId }).catch((error) => ({ message: error.message })); if (result.granted) dispatch("settings", { reminders: true }); setToast(result.message || (result.granted ? tr("{0} rappel(s) local(aux) programmé(s).", result.count) : tr("Autorisation de notification à accorder dans les réglages du téléphone."))); }}>{" "}{tr("Rappels hors ligne")}</button></div></>}
    {tab === "basket" && <><section className="gr-section-head"><div><p className="gr-eyebrow">{tr("JUSTE CE QU'IL VOUS FAUT")}</p><h2>{tr("Ouvrons d'abord les placards.")}</h2><p>{tr("Seuls les plats validés remplissent le panier ; cochez ce que vous avez ou ne voulez pas acheter.")}</p></div><button className="gr-secondary" onClick={() => setModal("stores")}><Icon name="settings" size={17} />{tr("Mes drives")}</button></section><div className="gr-basket-layout"><section className="gr-list-card"><header><h3>{tr("Ma liste")}{" "}<small>{list.length}{" "}{tr("ingrédients")}</small></h3><span>{tr("Déjà là / ne pas acheter")}</span></header>{list.map((line) => <div className={`gr-ingredient ${line.needed === 0 ? "owned" : ""}`} key={line.ingredientId}><label><input type="checkbox" checked={line.skipped} onChange={(event) => dispatch("pantry", { ingredientId: line.ingredientId, skip: event.target.checked })} aria-label={tr("Ne pas acheter {0}", line.label)} /><span className="gr-ingredient-icon"><Icon name="leaf" size={17}/></span><span><b>{line.label}</b><small>{line.quantity} {line.unit}{" "}{tr("nécessaires")}{line.owned > 0 ? tr(" · {0} déjà retirés", line.owned) : ""}</small></span></label><label className="gr-owned-qty"><span>{tr("J'ai")}</span><input type="number" aria-label={tr("Stock de {0}", line.label)} min="0" step={line.unit === "unit" ? 1 : 10} value={state.pantry[line.ingredientId]?.quantity || 0} onChange={(event) => dispatch("pantry", { ingredientId: line.ingredientId, quantity: Number(event.target.value) })} /><small>{line.unit}</small></label><b>{line.needed ? `≈ ${money(line.estimateCents)}` : tr("Déjà là ✓")}</b></div>)}{!list.length && <div className="gr-empty"><h3>{tr("Un panier qui attend vos envies.")}</h3><p>{tr("Choisissez vos repas, ou ajoutez un essentiel ci-dessous.")}</p></div>}<div className="gr-extra"><select value={extra} onChange={(event) => setExtra(event.target.value)} aria-label={tr("Ajouter un produit")}>{Object.values(INGREDIENTS).map((item) => <option key={item.id} value={item.id}>{item.label}</option>)}</select><button className="gr-secondary" onClick={() => dispatch("extra", { ingredientId: extra, quantity: INGREDIENTS[extra].referenceQuantity })}><Icon name="plus" size={16} />{tr("Ajouter")}</button></div></section><aside className="gr-summary"><span className="gr-badge">{tr("LE PANIER BIEN PENSÉ")}</span><h3>{comparison.best ? tr("Le meilleur panier trouvé.") : tr("Un vrai devis, sans inventer.")}</h3><strong>{comparison.best ? money(comparison.best.checkoutCents) : `≈ ${money(estimate)}`}</strong><p>{comparison.best ? tr("À payer, emballages et frais inclus") : tr("Repère de consommation · devis magasin incomplet")}</p><dl><div><dt>{tr("Plats validés")}</dt><dd>{accepted.length}</dd></div><div><dt>{tr("Ingrédients à acheter")}</dt><dd>{list.filter((line) => line.needed > 0).length}</dd></div><div><dt>{tr("Retirés grâce au placard")}</dt><dd>{list.filter((line) => line.needed === 0).length}</dd></div><div><dt>{tr("Budget indicatif")}</dt><dd>{money(state.settings.budgetCents)}</dd></div>{comparison.best && <div><dt>{tr("Cagnotte différée, non déduite")}</dt><dd>{money(comparison.best.loyaltyCents)}</dd></div>}</dl>{comparison.missing.length > 0 && <div className="gr-summary-note">{" "}{tr("Prix récents manquants pour")}{" "}{comparison.missing.length}{" "}{tr("ingrédient(s). Aucun total magasin fictif.")}</div>}<button className="gr-primary" disabled={!comparison.best || busy || Boolean(sync.pending) || !network} onClick={prepareCheckout}>{tr("Préparer le transfert")}{" "}<Icon name="arrow" size={17} /></button><button className="gr-secondary" onClick={() => shareShopping(shoppingText(state, comparison)).then(() => setToast(tr("Liste partagée ou copiée."))).catch((error) => setToast(error.message))}>{tr("Partager ma liste")}</button><small>{tr("2 enseignes maximum · validation finale chez l'enseigne · aucun paiement automatique")}</small></aside></div><section className="gr-comparison"><div className="gr-section-head"><div><p className="gr-eyebrow">{tr("ON COMPARE LES VRAIS CHIFFRES")}</p><h2>{tr("Un ou deux arrêts, pas plus.")}</h2></div><button className="gr-secondary" onClick={() => setModal("offer")}>{tr("＋ Relever un prix / une promo")}</button></div>{comparison.options.length ? <div className="gr-compare-grid">{comparison.options.map((option) => <article key={option.carts.map((cart) => cart.id).join("-")}><span>{option.ready ? "✓ Conditions remplies" : tr("À compléter")}</span><h3>{option.carts.map((cart) => RETAILERS.find((retailer) => retailer.id === cart.id).name).join(" + ")}</h3><strong>{money(option.checkoutCents)}</strong><p>{tr("Cagnotte future :")}{" "}{money(option.loyaltyCents)}{" "}{tr("· net théorique")}{" "}{money(option.effectiveCents)}</p>{option.warnings.map((warning) => <small key={warning}>{tr("Attention :")}{" "}{warning}</small>)}</article>)}</div> : <p className="gr-fine">{tr("Importez ou relevez les prix correspondant à votre magasin pour comparer des paniers complets, frais et minimums compris.")}</p>}{!comparison.optimal && comparison.options.length > 0 && <p className="gr-fine">{tr("Recherche bornée : meilleur résultat trouvé parmi les relevés, sans garantie d'optimum global.")}</p>}</section></>}
    {tab === "deals" && <><section className="gr-section-head"><div><p className="gr-eyebrow">{tr("DES PROMOS UTILES, PAS DU STOCK EN PLUS")}</p><h2>{tr("Les bons plans à vérifier.")}</h2><p>{tr("Catalogues officiels, prix datés et fidélité séparée du paiement.")}</p></div><div className="gr-actions"><button className="gr-secondary" onClick={() => setModal("prices")}>{tr("Importer CSV")}</button><button className="gr-primary" onClick={() => { setOfferCandidate(null); setModal("offer"); }}>{tr("Ajouter un relevé")}</button></div></section><div className="gr-retailer-grid">{RETAILERS.map((retailer) => <article key={retailer.id}><i className="gr-store-logo" style={{ background: retailer.color }}>{retailer.name.slice(0, 1)}</i><h3>{retailer.name}</h3><p>{retailer.note}</p><button className="gr-secondary" onClick={() => openRetailer(retailer.leaflet)}>{tr("Feuilleter les offres ↗")}</button><button className="gr-link" onClick={() => setModal("stores")}>{tr("Régler ma carte et mon magasin")}</button></article>)}</div><section className="gr-auto-catalogue"><h3>{tr("Catalogue public automatique")}</h3><p className="gr-fine">{!network ? tr("Hors ligne : dernière lecture disponible à la reconnexion.") : !catalogueScan ? tr("Lecture des sources officielles…") : catalogueScan.running ? tr("Recherche en cours sur les sources accessibles…") : tr("Dernière lecture : {0} · résultats à confirmer.", new Date(catalogueScan.completedAt).toLocaleString(LOCALE))}</p>{catalogueScan?.sources?.map((source, index) => <p className="gr-fine" key={`${source.url}-${index}`}>{RETAILERS.find((item) => item.id === source.storeId)?.name} · {source.kind === "catalogue" ? "catalogue" : tr("produit suivi")} : {source.status}</p>)}{catalogueScan?.products?.map((product, index) => <article className="gr-auto-product" key={`${product.sourceUrl}-${index}`}><div><strong>{product.label}</strong><small>{RETAILERS.find((item) => item.id === product.storeId)?.name} · {money(product.priceCents)} · {new Date(product.observedAt).toLocaleDateString(LOCALE)}</small></div><button className="gr-secondary" onClick={() => { setOfferCandidate(product); setModal("offer"); }}>{tr("Vérifier")}</button></article>)}<p className="gr-fine">{tr("Pages publiques uniquement, sans contourner blocages. Aucun prix n’est ajouté au panier avant vérification du magasin et du paquet ; les promotions et cartes fidélité nécessitent confirmation.")}</p></section><div className="gr-offers">{state.offers.map((offer) => <article key={offer.id}><span><Icon name="leaf" size={17}/></span><div><h3>{offer.label}</h3><p>{RETAILERS.find((item) => item.id === offer.storeId)?.name} · {offer.packQuantity} {INGREDIENTS[offer.ingredientId].unit}{" "}{tr("· relevé")}{" "}{new Date(offer.observedAt).toLocaleDateString(LOCALE)}</p><a href={offer.sourceUrl} target="_blank" rel="noreferrer">{tr("Voir la source ↗")}</a></div><b>{money(offer.priceCents - offer.instantDiscountCents)}<small>{offer.loyaltyCents ? tr("+ {0} cagnottés si éligible", money(offer.loyaltyCents)) : tr("Relevé à confirmer au panier")}</small></b><button className="gr-icon" aria-label={tr("Supprimer le relevé {0}", offer.label)} onClick={() => dispatch("offer-delete", { id: offer.id })}><Icon name="close" size={16} /></button></article>)}</div></>}
    {tab === "history" && <><section className="gr-section-head"><div><p className="gr-eyebrow">{tr("LES PETITES HABITUDES QUI COMPTENT")}</p><h2>{tr("Vos essentiels reviennent ici.")}</h2><p>{tr("Suggestions calculées uniquement à partir de vos commandes importées.")}</p></div><button className="gr-primary" onClick={() => setModal("orders")}>{tr("Importer mon historique")}</button></section>{frequent.length > 0 && <div className="gr-frequent">{frequent.map((item) => <button key={item.id} onClick={() => dispatch("extra", { ingredientId: item.id, quantity: item.referenceQuantity })}><span><Icon name="leaf" size={17}/></span><b>{item.label}</b><small>{item.count} commandes</small><Icon name="plus" size={16} /></button>)}</div>}<div className="gr-order-list">{state.orders.map((order) => <article key={order.id}><span><Icon name="cart" /></span><div><h3>{RETAILERS.find((item) => item.id === order.storeId)?.name}</h3><p>{new Date(`${order.date}T12:00:00`).toLocaleDateString(LOCALE)} · {order.lines.length}{" "}{tr("produits · historique importé")}</p><small>{order.lines.map((line) => INGREDIENTS[line.ingredientId].label).join(", ")}</small></div><b>{money(order.lines.reduce((sum, line) => sum + line.priceCents, 0))}</b></article>)}</div>{!state.orders.length && <div className="gr-empty"><h3>{tr("On apprend vos habitudes avec vous.")}</h3><p>{tr("Aucune commande inventée : importez vos relevés, puis retrouvez vos produits fréquents.")}</p><button className="gr-secondary" onClick={() => setModal("orders")}>{tr("Importer un premier historique")}</button></div>}<div className="gr-tools"><button className="gr-secondary" onClick={associate}>{" "}{tr("Associer cet appareil au canal Courses")}</button><button className="gr-secondary" onClick={() => setModal("devices")}>{tr("Gérer les appareils")}</button><p className="gr-fine">{tr("Endpoint dédié authentifié, à publier séparément si souhaité ; aucun accès aux agents ou fichiers. Sans VPN : travail local, puis synchronisation automatique au retour réseau, application ouverte ou reprise.")}</p></div></>}
    <footer className="gr-bottom"><span><Icon name="leaf" size={17} />{tr("Simple, varié, à votre rythme.")}</span><small>{tr("Repères indicatifs, prix datés seulement · aucune commande automatique")}</small><div>{isNative && <button className="gr-link" onClick={() => window.dispatchEvent(new Event("noyau:configure-native"))}>{tr("Serveur / VPN")}</button>} <button className="gr-link" onClick={() => setModal("household")}>{tr("Mes préférences")}</button></div></footer>
    {toast && <div className="gr-toast" role="status">{toast}<button onClick={() => setToast("")} aria-label={tr("Fermer le message")}>×</button></div>}
    {recipe && <Modal title={recipe.title} subtitle={recipe.subtitle} onClose={() => setSelected(null)} wide><div className="gr-detail"><RecipePhoto recipe={recipe} /><div className="gr-detail-info"><div className="gr-recipe-arrows"><button className="gr-secondary" onClick={() => changeRecipe(-1)}>{tr("← Précédente")}</button><button className="gr-secondary" onClick={() => changeRecipe(1)}>{tr("Suivante →")}</button></div><div className="gr-detail-stats"><span>{recipe.minutes} min</span><span> {state.settings.people} portions</span><span>≈ {money(recipe.estimateCents / recipe.servings)}{" "}{tr("/ pers.")}</span></div><h3>{tr("Dans votre panier")}</h3><ul className="gr-detail-ingredients">{recipe.ingredients.map((item) => <li key={item.ingredientId}><span>{INGREDIENTS[item.ingredientId].label}</span><b>{Math.round(item.quantity * state.settings.people / recipe.servings)} {INGREDIENTS[item.ingredientId].unit}</b></li>)}</ul><p className="gr-fine">{tr("Allergènes identifiés :")}{" "}{recipe.allergens.join(", ") || tr("aucun dans la recette de base")}{tr(". Vérifiez les étiquettes et traces.")}{" "}{recipe.imageDisclosure}.</p>{recipe.sourceUrl && <button className="gr-link" onClick={() => openRetailer(recipe.sourceUrl)}>{tr("Voir la recette source ↗")}</button>}{recipe.familyId === "personal" && <div className="gr-tools"><button className="gr-secondary" onClick={() => { setEditingRecipe(recipe); setSelected(null); setModal("custom-recipe"); }}>{tr("Modifier ma recette")}</button><button className="gr-link" onClick={() => { if (window.confirm(tr("Supprimer cette recette personnelle ?")) && dispatch("custom-recipe-delete", { id: recipe.id })) setSelected(null); }}>{tr("Supprimer")}</button></div>}<div className="gr-detail-cta"><button className="gr-primary" onClick={() => chooseRecipe(recipe.id)}>{tr("Ce plat me plaît")}{" "}<Icon name="check" size={18} /></button><button className="gr-secondary" onClick={() => favorite(recipe.id)}>{tr("♡ Favori")}</button><button className="gr-link" onClick={() => { dispatch("preference", { recipeId: recipe.id, value: "disliked" }); setSelected(null); }}>{tr("Moins de ce plat")}</button></div></div><div className="gr-steps"><h3>{tr("On passe en cuisine.")}</h3>{recipe.steps.map((step, index) => <div key={step}><b>{index + 1}</b><p>{step}</p></div>)}<small>{tr("Temps indicatifs : adapter à votre matériel, à la taille des morceaux et à la cuisson complète des aliments.")}</small></div></div></Modal>}
    {modal === "custom-recipe" && <CustomRecipeForm recipe={editingRecipe} request={request} dispatch={dispatch} onClose={() => setModal(null)} notify={setToast} />}{modal === "household" && <Household state={state} dispatch={dispatch} onClose={() => setModal(null)} notify={setToast} />}{modal === "stores" && <StoreSettings state={state} dispatch={dispatch} onClose={() => setModal(null)} />}{modal === "offer" && <OfferForm candidate={offerCandidate} state={state} dispatch={dispatch} request={request} onClose={() => { setOfferCandidate(null); setModal(null); }} notify={setToast} />}{modal === "orders" && <OrderImport state={state} dispatch={dispatch} onClose={() => setModal(null)} notify={setToast} />}{modal === "prices" && <PriceImport state={state} dispatch={dispatch} onClose={() => setModal(null)} notify={setToast} />}{modal === "devices" && <GroceryDevices request={request} onClose={() => setModal(null)} notify={setToast} />}
    {checkout && <Modal title={tr("Votre liste est prête.")} subtitle={tr("TRANSFERT ASSISTÉ, PAS COMMANDE CONFIRMÉE")} onClose={() => setCheckout(null)}><p className="gr-fine">{checkout.message}</p>{checkout.carts.map((cart) => <article className="gr-checkout-cart" key={cart.id}><h3>{cart.retailer.name} · {money(cart.subtotalCents + cart.feesCents)}</h3><ul>{cart.lines.map((line) => <li key={line.ingredientId}>{line.label} · {line.packs}{" "}{tr("paquet(s) ·")}{" "}{money(line.checkoutCents)}<small>{tr("Surplus :")}{" "}{line.surplus} {line.unit}</small></li>)}</ul><button className="gr-primary" onClick={() => openRetailer(cart.retailer.url)}>{tr("Ouvrir mon compte officiel ↗")}</button></article>)}<button className="gr-secondary" onClick={() => shareShopping(checkout.text)}>{tr("Partager / copier la liste")}</button></Modal>}
  </div>;
}
